    @Override
    public Collection<ResourceFolderType> getApplicableResourceFolders() {
        return Collections.singletonList(ResourceFolderType.DRAWABLE);
    }

    @Override
    public void checkResourceFolder(ResourceContext context) {
        File folder = context.file;
        if (folder.getName().equals("drawable")) { //$NON-NLS-1$
            File[] files = folder.listFiles();
            if (files != null) {
                for (File file : files) {
                    String name = file.getName();
                    if (endsWith(name, DOT_PNG) || endsWith(name, DOT_JPG) ... ) {
                        context.report(ICON_LOCATION, Location.create(file), ...);
                    }
                }
            }
        }
    }
}
```
